package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import org.joml.Quaterniond;
import org.junit.jupiter.api.Test;
import java.nio.file.*;
import static org.junit.jupiter.api.Assertions.*;

class NativeSpaceNavigationTest {
    private static NativeSpaceNavigation.Marker project(double x,double y,double z){return NativeSpaceNavigation.project(new Point(x,y,z),Math.PI/2,2,.05,.1);}
    @Test void frontCentreAndPerspective(){var a=project(0,0,-10);assertFalse(a.edge());assertEquals(.5,a.x());assertEquals(.5,a.y());var b=project(10,4,-10);assertFalse(b.edge());assertEquals(.75,b.x(),1e-12);assertEquals(.3,b.y(),1e-12);}
    @Test void allEdgesAndCornersStayInside(){for(double x:new double[]{-100,0,100})for(double y:new double[]{-100,0,100})for(double z:new double[]{-1,0,1}){var a=project(x,y,z);assertTrue(Double.isFinite(a.x())&&Double.isFinite(a.y()));assertTrue(a.x()>=.05-1e-12&&a.x()<=.95+1e-12);assertTrue(a.y()>=.1-1e-12&&a.y()<=.9+1e-12);if(a.edge())assertTrue(Math.abs(a.x()-.05)<1e-12||Math.abs(a.x()-.95)<1e-12||Math.abs(a.y()-.1)<1e-12||Math.abs(a.y()-.9)<1e-12);}}
    @Test void behindNeverReversesShortestTurn(){assertTrue(project(1,0,10).x()>.5);assertTrue(project(-1,0,10).x()<.5);assertTrue(project(0,1,10).y()<.5);assertTrue(project(0,-1,10).y()>.5);assertEquals(.95,project(0,0,10).x(),1e-12);assertTrue(project(0,0,10).edge());}
    @Test void cameraPlaneIsContinuousAndArrowUsesPixelAspect(){var front=project(1,1,-1e-9);var back=project(1,1,1e-9);assertEquals(front,back);assertEquals(-Math.PI/4,front.angle(),1e-12);}
    @Test void fovAndAspectDetermineProjection(){var p=NativeSpaceNavigation.project(new Point(1,0,-10),Math.toRadians(60),1,.05,.05);assertEquals(.5+1/(20*Math.tan(Math.PI/6)),p.x(),1e-12);assertTrue(p.x()>project(1,0,-10).x());}
    @Test void closingHasCorrectSignUnitsAndIgnoresTangentialMotion(){var toward=new Point(10,0,0);assertEquals(40,NativeSpaceNavigation.closing(toward,new Point(3,999,0),new Point(1,0,0)));assertEquals(-40,NativeSpaceNavigation.closing(toward,new Point(-1,0,0),new Point(1,0,0)));assertEquals(0,NativeSpaceNavigation.closing(toward,new Point(1,5,0),new Point(1,0,0)));assertEquals(0,NativeSpaceNavigation.closing(GroundEphemeris.ZERO,new Point(1,0,0),GroundEphemeris.ZERO));}
    @Test void referenceSpeedUsesUniverseDriftNotLevelMotion(){var frame=new NativeSpace.Frame(new Quaterniond().rotationXYZ(.3,.7,1),NativeSpace.ORIGIN,0,GroundEphemeris.ZERO,new Point(3,4,0),900);assertEquals(100,NativeSpaceNavigation.speed(frame));}
    @Test void angleIsLevelDownNotCameraAim(){assertEquals(0,NativeSpaceNavigation.angle(new Point(0,-20,0)));assertEquals(90,NativeSpaceNavigation.angle(new Point(3,0,4)));assertEquals(180,NativeSpaceNavigation.angle(new Point(0,1,0)));assertEquals(.9,NativeSpaceNavigation.angle(new Point(Math.sin(Math.toRadians(.9)),-Math.cos(Math.toRadians(.9)),0)),1e-12);assertTrue(NativeSpaceNavigation.angle(new Point(Math.sin(Math.toRadians(1.1)),-Math.cos(Math.toRadians(1.1)),0))>1);assertEquals(0,NativeSpaceNavigation.angle(GroundEphemeris.ZERO));}
    @Test void telemetryIncludesReferenceOrbitAndTargetCentreVelocity(){var model=NativePlanetSystem.model();double tick=900;var frame=new NativeSpace.Frame(new Quaterniond().rotationY(.7),NativeSpace.ORIGIN,0,GroundEphemeris.ZERO,new Point(2,3,4),900);var eye=model.at(1,tick).center().add(new Point(NativePlanetShape.of(1).radius()+500,0,0));var r=NativeSpaceNavigation.read(model,frame,eye,1,tick);assertEquals(500,r.distance(),1e-8);assertEquals(-20*(frame.drift().x()+model.at(0,tick).velocity().x()-model.at(1,tick).velocity().x()),r.closing(),1e-8);var changed=frame.toward(1,model,tick);assertEquals(r.closing(),NativeSpaceNavigation.read(model,changed,eye,1,tick).closing(),1e-8);}
    @Test void interpolatedFrameAndLargeCoordinatesAgreeWithRenderer(){var model=NativePlanetSystem.model();var eye=new Point(1e10,2e10,-3e10);var frame=new NativeSpace.Frame(new Quaterniond().rotationXYZ(.3,.8,.2),NativeSpace.ORIGIN,0);var target=eye.add(new Point(10,20,-30));assertEquals(frame.levelVector(new Point(10,20,-30)),NativeSpaceView.relative(frame,eye,target));var after=frame.turned(new Quaterniond().rotationX(.4),NativeSpace.ORIGIN);var blend=NativeSpace.Frame.interpolate(frame,after,NativeSpace.ORIGIN,.5,model,900);assertEquals(0,NativeSpaceView.relative(blend,eye,target).sub(blend.levelVector(target.sub(eye))).length(),1e-10);}
    @Test void sourceContractRestrictsLayerAndProbeToDisplayedRegionReadings()throws Exception{
        var root=Path.of("src/main/java/dev/starfold");String s=Files.readString(root.resolve("NativeSpaceNavigationClient.java"));
        assertTrue(s.contains("NativeSpaceClient.active()&&!NativeGroundFlightClient.controlled()&&!mc.options.hideGui&&mc.screen==null"));assertTrue(s.contains("if(!chart&&!visible())return"));assertTrue(s.contains("if(mc.options.hideGui||mc.screen!=null||NativeHelmClient.body()==null)return"));assertTrue(s.contains("NativeFlightWidgets.view(g,NativeHelmClient.viewLabel(),NativeHelmClient.viewFlash())"));assertTrue(s.contains("if(snapshot==null||level!=mc.level)return"));
        assertTrue(s.contains("RegisterGuiLayersEvent"));assertTrue(s.contains("AFTER_LEVEL"));assertTrue(s.contains("context.projectionMatrix()"));assertTrue(s.contains("context.positionMatrix()"));assertTrue(s.contains("NativeSpaceClient.frame()"));assertTrue(s.contains("NativeSpaceClient.arriving()"));assertTrue(s.contains("NativeSpaceView.nearest(model,eye,tick,4)"));assertTrue(s.contains("helm.logicalPose().position()"));assertFalse(s.contains("NativeSpaceApproach.APPROACH"));
        assertTrue(s.indexOf("receipt=\" | instruments tier \"")>s.indexOf("NativeFlightWidgets.render(g,snapshot)"));assertTrue(s.contains("mc.level.getGameTime()-drawnTick<=2?receipt"));assertTrue(Files.readString(root.resolve("DevProbe.java")).contains("space(q.position())+NativeSpaceNavigationClient.probeReading()"));assertTrue(Files.readString(root.resolve("NativeGroundClient.java")).contains("NativeSpaceNavigationClient.initialize(modBus)"));
    }
    @Test void bothLanguagesContainEveryHudKey()throws Exception{String s=Files.readString(Path.of("src/main/java/dev/starfold/NativeSpaceNavigationClient.java"));for(String language:new String[]{"en_us","zh_cn"}){var json=com.google.gson.JsonParser.parseString(Files.readString(Path.of("src/main/resources/assets/starfold/lang/"+language+".json"))).getAsJsonObject();var matcher=java.util.regex.Pattern.compile("\"(hud\\.starfold\\.space_[a-z_]+)\"").matcher(s);int count=0;while(matcher.find()){assertTrue(json.has(matcher.group(1)));count++;}assertEquals(1,count);for(String key:new String[]{"scope_required","free","arrival","chart","caption","boost","relative","closing","bearing","clearance"})assertTrue(json.has("hud.starfold.instrument_"+key));}}
}
